import type { AttemptRecord, SessionMeta } from '../game/core/RaceState';

type Cell = string | number | boolean | null | undefined;

/** UTF-8 byte order mark (U+FEFF) so Excel reads Bahasa Melayu text correctly. */
export const BOM = String.fromCharCode(0xfeff);

/**
 * Neutralise spreadsheet formula injection. A text cell that starts with =, +, -, @, tab or carriage return
 * would be executed as a formula by Excel/Sheets/LibreOffice, so it is prefixed with an apostrophe.
 * Numbers generated by the app are written as numbers and are never prefixed.
 */
export function escapeCell(value: Cell): string {
  if (value === null || value === undefined) return '';
  if (typeof value === 'number') return Number.isFinite(value) ? String(value) : '';
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  let text = value;
  if (/^[=+\-@\t\r]/.test(text)) text = `'${text}`;
  if (/[",\r\n]/.test(text)) text = `"${text.replace(/"/g, '""')}"`;
  return text;
}

type Column = { header: string; value: (r: AttemptRecord, s: SessionMeta | undefined) => Cell };

export const CSV_COLUMNS: readonly Column[] = [
  { header: 'session_id', value: (r) => r.sessionId },
  { header: 'session_seed', value: (r) => r.seed },
  { header: 'pack_id', value: (r) => r.packId },
  { header: 'pack_version', value: (r) => r.packVersion },
  { header: 'year', value: (r) => r.year },
  { header: 'topic_id', value: (r) => r.topicId },
  { header: 'sk', value: (r) => r.standardKandungan },
  { header: 'sp', value: (r) => r.standardPembelajaran },
  { header: 'template_id', value: (r) => r.templateId },
  { header: 'difficulty_band', value: (r) => r.difficultyBand },
  { header: 'level', value: (r) => r.level },
  { header: 'player', value: (r) => r.playerName },
  { header: 'timestamp_iso', value: (r) => new Date(r.timestampMs).toISOString() },
  { header: 'item_index', value: (r) => r.itemIndex },
  { header: 'question_id', value: (r) => r.questionId },
  { header: 'attempt_number', value: (r) => r.attemptNumber },
  { header: 'submitted_answer', value: (r) => r.submittedAnswer },
  { header: 'normalized_answer', value: (r) => r.normalizedAnswer },
  { header: 'correct', value: (r) => r.correct },
  { header: 'outcome', value: (r) => r.outcome },
  { header: 'elapsed_ms', value: (r) => r.elapsedMs },
  { header: 'first_action_ms', value: (r) => r.firstActionMs },
  { header: 'hint_used', value: (r) => r.hintUsed },
  { header: 'support_used', value: (r) => r.supportUsed },
  { header: 'step_delta', value: (r) => r.stepDelta },
  { header: 'progress_after', value: (r) => r.progressAfter },
  // Records saved before cruise movement have no speed effect; the cell is then left empty.
  { header: 'speed_effect', value: (r) => r.speedEffect },
  { header: 'parameters_json', value: (r) => r.parameters },
];

/** Build CSV text (UTF-8, CRLF, header row). Prefixed with a BOM so Excel reads Bahasa Melayu text correctly. */
export function attemptsToCsv(records: readonly AttemptRecord[], session?: SessionMeta): string {
  const lines = [CSV_COLUMNS.map((c) => escapeCell(c.header)).join(',')];
  for (const record of records)
    lines.push(CSV_COLUMNS.map((c) => escapeCell(c.value(record, session))).join(','));
  return `${BOM}${lines.join('\r\n')}\r\n`;
}

export function csvFileName(session: Pick<SessionMeta, 'sessionId' | 'startedAtMs'>): string {
  const d = new Date(session.startedAtMs);
  const pad = (n: number): string => String(n).padStart(2, '0');
  const stamp = `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}`;
  return `mathracing-${stamp}-${session.sessionId.replace(/[^A-Za-z0-9_-]/g, '')}.csv`;
}

/** Start a browser download of the CSV text. Returns the file name used. */
export function downloadCsv(text: string, fileName: string): void {
  const blob = new Blob([text], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  a.rel = 'noopener';
  document.body.appendChild(a);
  a.click();
  a.remove();
  // Revoke after the browser has had time to start the download.
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}
